/**
 * `public/brand/sam-group-mark-256.png`, byte for byte, as a data URI — for the one placement that
 * must paint with the HTML itself: the home page loader, whose whole job is to show the mark. As a
 * separate file it waited behind fonts and scripts (low priority) and arrived seconds late on slow
 * connections. `logo-mark-inline.spec.ts` fails if this ever differs from the file.
 *
 * Generated; do not edit by hand. To regenerate after the file changes:
 *   node -e "console.log(require('fs').readFileSync('public/brand/sam-group-mark-256.png').toString('base64'))"
 */
export const LOGO_MARK_DATA_URI =
  "data:image/png;base64,";
